<?php $page_title='Donations'; require 'layout.php';
$rows=$pdo->query("SELECT f.id,f.title,f.quantity,f.unit,f.status,f.created_at,u.name donor,COUNT(r.id) requests FROM food_donations f JOIN users u ON u.id=f.donor_id LEFT JOIN food_requests r ON r.food_id=f.id GROUP BY f.id ORDER BY f.created_at DESC")->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / DONATIONS</span><h1>Donation Records</h1><p>Track donation activity, requests and completion.</p></div></section><div class="mini-stat-grid"><div><b><?=count($rows)?></b><span>Total donations</span></div><div><b><?=count(array_filter($rows,fn($x)=>$x['status']==='completed'))?></b><span>Completed</span></div><div><b><?=array_sum(array_map(fn($x)=>(int)$x['quantity'],$rows))?></b><span>Total quantity</span></div></div><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>#</th><th>Donation</th><th>Donor</th><th>Quantity</th><th>Requests</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=intval($r['id'])?></td><td><b><?=e($r['title'])?></b></td><td><?=e($r['donor'])?></td><td><?=intval($r['quantity'])?> <?=e($r['unit'])?></td><td><?=intval($r['requests'])?></td><td><span class="badge <?=badge_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
